import fs from 'node:fs/promises';
import {gunzipSync} from 'node:zlib';
import path from 'node:path';
const server='backend/server.mjs';
const renderer='backend/services/noventia-pdf.cjs';
const original=await fs.readFile(server,'utf8');
const header="import noventiaPdf from './services/noventia-pdf.cjs';\nconst { disenar } = noventiaPdf;\n";
if(original.includes(header)) { console.log('El diseño ya está instalado.');process.exit(0); }
let next=original;
for(const [oldText,newText] of [["function serveBytes(res,bytes,contentType,downloadName){", "async function pdfParaDescarga(factura, leerXml, original) {\n  if (factura.ambienteTimbrado !== \"PRODUCCION\" || factura.estatus !== \"TIMBRADA\" || !factura.uuid) return original;\n  try {\n    const xml = await leerXml();\n    return await disenar(xml, original, factura.folioInterno, factura.uuid);\n  } catch {\n    console.warn(\"Se entrega el PDF del proveedor para el folio\", factura.folioInterno);\n    return original;\n  }\n}\n\nfunction serveBytes(res,bytes,contentType,downloadName){"], ["      return serveBytes(res,documento.bytes,documento.contentType,documento.nombre);", "      if(tipo===\"pdf\"){\n        const id=decodeURIComponent(parts[4]);\n        const factura=await portalFacturas.facturaPropia(session.user.id,id);\n        const leerXml=async ()=>(await portalFacturas.documento(session.user.id,id,\"xml\")).bytes;\n        const pdf=await pdfParaDescarga(factura,leerXml,documento.bytes);\n        return serveBytes(res,pdf,documento.contentType,documento.nombre);\n      }\n      return serveBytes(res,documento.bytes,documento.contentType,documento.nombre);"], ["        return serveBytes(res,bytes,mime[`.${tipo}`", "        const salida=tipo===\"pdf\" ? await pdfParaDescarga(factura,()=>documentStorage.download(factura.xmlStoragePath),bytes) : bytes;\n        return serveBytes(res,salida,mime[`.${tipo}`"], ["      return serveFile(res, path.join(storageRoot,rel), `${factura.folioOrigen || factura.id}.${tipo}`);", "      if(tipo===\"pdf\" && factura.ambienteTimbrado===\"PRODUCCION\" && factura.estatus===\"TIMBRADA\"){\n        const original=await fs.readFile(path.join(storageRoot,rel));\n        const pdf=await pdfParaDescarga(factura,()=>fs.readFile(path.join(storageRoot,factura.xmlRelativePath)),original);\n        return serveBytes(res,pdf,mime[\".pdf\"],`${factura.folioOrigen || factura.id}.pdf`);\n      }\n      return serveFile(res, path.join(storageRoot,rel), `${factura.folioOrigen || factura.id}.${tipo}`);"]]){
  if(next.split(oldText).length!==2)throw Error('La versión de backend/server.mjs difiere de la esperada. Se conservó tu instalación.');
  next=next.replace(oldText,()=>newText);
}
const backup=await fs.mkdtemp('respaldo-pdf-noventia-');
await fs.writeFile(path.join(backup,'server.mjs'),original);
await fs.writeFile(renderer,gunzipSync(Buffer.from("",'base64')),{flag:'wx'});
const tmp=server+'.noventia-'+process.pid;
try{await fs.writeFile(tmp,header+next,{flag:'wx'});await fs.rename(tmp,server);}
catch(error){await fs.rm(tmp,{force:true});await fs.rm(renderer,{force:true});throw error;}
console.log('Diseño PDF instalado. Respaldo: '+backup);
